// RSFA — Mortgage App household resolver (scenario 9447215, module 301).
//
// Body of the Make "Code" module (code:ExecuteCode, JavaScript) in
// "M.com: New Form Submission in IQ/MA/KQ (Jun 2026)".
// NEVER write double curly braces anywhere in this file, comments included: Make evaluates them as
// mapping expressions inside the Code field and the module then returns an empty result.
// Keep the single top-level return at the end (a nested return gives an empty result in Make).
//
// Inputs (mapped in the module):
//   lookup   Monday GraphQL data of module 300: { submission: [item], contacts: [board] } (object or JSON text)
//   boardId  board of the new submission (webhook)
//   pulseId  item ID of the new submission (webhook)
// Output:
//   { applies, reason, household, cpId, contactIds, firstContactId, columnValues }
//   household  "single"    every matched Contact that has a Client Profile points to the same one profile
//              "ambiguous" matched Contacts point to more than one Client Profile
//              "none"      no matched Contact has a Client Profile, or no Contact matched
//   firstContactId  a matched Contact of the single household (used by module 143), else null
//   columnValues    JSON text for change_multiple_column_values, or null when nothing must be written
// Rules:
//   - single:    link the Client Profile, and set Contacts = the Client Profile's Contacts
//                (fallback: the matched Contacts of that profile if the profile lists none)
//   - ambiguous / none with matched Contacts: link only the matched Contacts (no Client Profile)
//   - never overwrite a Client Profile that is already linked; never touch a non-empty Contacts
//     column unless the household is single
// IDs only: this module never outputs names or emails.

const MORTGAGE_APP_BOARD = '5025483251';
const CP_COLUMN = 'board_relation_mm6fr9y4';
const CONTACTS_COLUMN = 'board_relation_mkzqbtd0';

function parse(value) {
  if (value === undefined || value === null || value === '') return null;
  return typeof value === 'string' ? JSON.parse(value) : value;
}
function first(list) { return Array.isArray(list) && list.length ? list[0] : null; }
function ids(rel) { return rel && Array.isArray(rel.linked_item_ids) ? rel.linked_item_ids.map(String) : []; }
function uniq(list) { const out = []; for (const x of list) if (!out.includes(x)) out.push(x); return out; }
function sameSet(a, b) { return a.length === b.length && a.every((x) => b.includes(x)); }

function resolve(input) {
  const out = { applies: false, reason: null, household: 'none', cpId: null, contactIds: [], firstContactId: null, columnValues: null };
  if (String(input.boardId) !== MORTGAGE_APP_BOARD) { out.reason = 'NOT_MORTGAGE_APP'; return out; }
  const data = parse(input.lookup);
  if (!data) { out.reason = 'NO_LOOKUP_DATA'; return out; }

  const submission = first(data.submission);
  if (!submission || String(submission.id) !== String(input.pulseId)) { out.reason = 'SUBMISSION_NOT_FOUND'; return out; }
  const currentCp = ids(first(submission.cp));
  const currentContacts = ids(first(submission.contacts));

  const board = first(data.contacts);
  const items = (board && board.items_page && board.items_page.items) || [];
  const matched = [];
  const profileOf = {};   // contactId -> [cpId]
  const members = {};     // cpId -> [contactId]
  for (const item of items) {
    const contactId = String(item.id);
    if (!matched.includes(contactId)) matched.push(contactId);
    const rel = first(item.cp) || {};
    profileOf[contactId] = ids(rel);
    for (const li of rel.linked_items || []) members[String(li.id)] = ids(first(li.members));
  }
  const profiles = uniq(matched.flatMap((c) => profileOf[c]));

  const values = {};
  if (profiles.length === 1) {
    const cpId = profiles[0];
    const ofProfile = matched.filter((c) => profileOf[c].includes(cpId));
    out.household = 'single';
    out.cpId = cpId;
    out.contactIds = (members[cpId] && members[cpId].length) ? members[cpId] : ofProfile;
    out.firstContactId = ofProfile[0] || null;
    if (currentCp.length) { out.reason = 'CLIENT_PROFILE_ALREADY_LINKED'; return out; }
    values[CP_COLUMN] = { item_ids: [Number(cpId)] };
    if (!sameSet(currentContacts, out.contactIds)) values[CONTACTS_COLUMN] = { item_ids: out.contactIds.map(Number) };
    out.reason = 'SINGLE_HOUSEHOLD';
  } else {
    out.household = profiles.length > 1 ? 'ambiguous' : 'none';
    out.contactIds = matched;
    out.reason = matched.length ? (profiles.length > 1 ? 'AMBIGUOUS_HOUSEHOLD' : 'NO_CLIENT_PROFILE') : 'NO_CONTACT_MATCHED';
    if (matched.length && !currentContacts.length && !currentCp.length) values[CONTACTS_COLUMN] = { item_ids: matched.map(Number) };
  }
  if (Object.keys(values).length) { out.applies = true; out.columnValues = JSON.stringify(values); }
  return out;
}

// Node (tests) export. In Make's runtime `module` has no `exports`, so this is skipped.
if (typeof module !== 'undefined' && module && module.exports) {
  module.exports = { resolve };
}
return typeof input !== 'undefined' ? resolve(input) : undefined;

mapper.queryBody:
mutation ($boardId: ID!, $itemId: ID!, $clientName: String!) {
  change_simple_column_value(
    board_id: $boardId
    item_id: $itemId
    column_id: "name"
    value: $clientName
  ) {
    id
    name
  }
}

